import http from 'node:http';
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { fileURLToPath } from 'node:url';

export const START_CASH = 4_000_000;
export const START_PRICE = 2_000_000;
export const AUCTION_MS = 10_000;
export const COUNTDOWN_MS = 2_900;
export const RESULT_MS = 1_300;
export const MIN_PLAYERS = 2;
export const MAX_PLAYERS = 6;
export const MIN_HUMAN_PLAYERS = 2;
export const MAX_BOTS = 4;
// Te same imiona co boty w trybie dla jednego gracza (BOT_NAMES w index.html).
export const BOT_NAMES = ['Piotr', 'Wojciech', 'Kuba', 'Aneta'];

// Kolejność musi odpowiadać LISTINGS w index.html.
export const LISTING_RENTS = [
  850, 2700, 1650, 2050, 1200,
  1500, 2450, 1350, 1800, 2800,
  2650, 1950, 1600, 1100, 1000,
  900, 1750, 950, 2550, 2950,
  1250, 2100, 1050, 1450, 2350,
  1400, 1150, 1300, 2600, 1700,
  1550,
  800, 825, 975, 1025, 1075, 1125, 1225, 1275, 1375, 1425,
  1475, 1525, 1575, 1675, 1725, 1775, 1825, 1850, 1900, 1925,
  1975, 2000, 2025, 2075, 2125, 2150, 2250, 2300,
  875, 925, 1175, 1325, 1625, 1875, 2200, 2500, 2275, 2400, 2750,
  3200, 3300, 3100, 3500, 3800, 3700, 3900, 3400, 3600
];

// Oferty od indeksu MYSTERY_START_INDEX w górę (do DIVISIBLE_START_INDEX
// wyłącznie) to "mystery listingi" bez zdjęć (patrz index.html) — klient
// pokazuje zamiast ceny tylko przedział.
export const MYSTERY_START_INDEX = 59;

// Oferty od indeksu DIVISIBLE_START_INDEX w górę to duże (24 m²) mieszkania,
// które po zakupie można podzielić na DIVIDE_UNITS klitek za DIVIDE_COST.
export const DIVISIBLE_START_INDEX = 70;
export const DIVIDE_COST = 500_000;
export const DIVIDE_UNITS = 2;
export const dividedRentPerUnit = rent => Math.round((rent + 500) / DIVIDE_UNITS);

// "Prawdziwi ludzie": poniżej pewnej ceny na ofertę czeka ktoś, kto faktycznie
// chce w niej zamieszkać, nie inwestor. Wzór identyczny jak w index.html
// (familyThresholdFor) — musi dawać ten sam wynik po obu stronach, inaczej
// gracze w tym samym pokoju zobaczą rozjechane wyniki.
const FAMILY_THRESHOLD_MIN_FRAC = .03;
const FAMILY_THRESHOLD_MAX_FRAC = .10;
const RENT_MIN = Math.min(...LISTING_RENTS);
const RENT_MAX = Math.max(...LISTING_RENTS);
export const familyThresholdFor = listingId => {
  const rent = LISTING_RENTS[listingId];
  const span = RENT_MAX - RENT_MIN;
  const ratio = span > 0 ? (rent - RENT_MIN) / span : 0;
  const frac = FAMILY_THRESHOLD_MIN_FRAC + ratio * (FAMILY_THRESHOLD_MAX_FRAC - FAMILY_THRESHOLD_MIN_FRAC);
  return Math.round(START_PRICE * frac);
};

const EXTRA_LISTINGS_HTML = `        { city: 'Dawna pralnia · stół wielofunkcyjny', area: 10, rent: 1250, photos: syntheticPhoto(21) },
        { city: 'Kamienica · prywatny komin', area: 9, rent: 2100, photos: syntheticPhoto(22) },
        { city: 'Kotłownia · instalacje w cenie', area: 9, rent: 1050, photos: syntheticPhoto(23) },
        { city: 'Pod zjazdem · malejąca wysokość', area: 11, rent: 1450, photos: syntheticPhoto(24) },
        { city: 'Balkon · panoramiczny standard', area: 7, rent: 2350, photos: syntheticPhoto(25) },
        { city: 'Poddasze · strefa schylania', area: 6, rent: 1400, photos: syntheticPhoto(26) },
        { city: 'Dawna chłodnia · stała temperatura', area: 9, rent: 1150, photos: syntheticPhoto(27) },
        { city: 'Suterena · poziom chodnika', area: 12, rent: 1300, photos: syntheticPhoto(28) },
        { city: 'Dawny kiosk · witryna miejska', area: 8, rent: 2600, photos: syntheticPhoto(29) },
        { city: 'Kontener · moduł miejski', area: 13, rent: 1700, photos: syntheticPhoto(30) },
        { city: 'Boazeria · klasyka premium', area: 12, rent: 1550, photos: syntheticPhoto(31) }`;

// W samodzielnym pliku aktualizacyjnym ten pusty zbiór jest zastępowany
// osadzonymi zdjęciami 21–68. Pełny projekt korzysta z plików w assets/.
const EMBEDDED_ASSETS = new Map();

// W lekkiej aktualizacji zdjęcia są osobnymi plikami w katalogu assets/.
// W jednoplikowej aktualizacji null jest zastępowany pełną, aktualną stroną.
// Dzięki temu do wdrożenia wystarcza podmiana samego server.mjs.
const EMBEDDED_INDEX_HTML = Buffer.from('', 'base64').toString('utf8');

const rootDirectory = path.dirname(fileURLToPath(import.meta.url));

const rooms = new Map();
let previousDeck = [];

const json = (response, status, body) => {
  response.writeHead(status, {
    'content-type': 'application/json; charset=utf-8',
    'cache-control': 'no-store'
  });
  response.end(JSON.stringify(body));
};

const cleanName = value => String(value || '')
  .trim()
  .replace(/[<>]/g, '')
  .slice(0, 16);

const shuffle = input => {
  const values = input.slice();
  for (let index = values.length - 1; index > 0; index -= 1) {
    const other = crypto.randomInt(index + 1);
    [values[index], values[other]] = [values[other], values[index]];
  }
  return values;
};

const MYSTERY_QUOTA = 2;
const DIVISIBLE_QUOTA = 1;

const createVariedDeck = (count, options = {}) => {
  const previous = new Set(previousDeck);
  const all = LISTING_RENTS.map((_, index) => index);
  const mysteryPool = all.filter(index => index >= MYSTERY_START_INDEX && index < DIVISIBLE_START_INDEX);
  const divisiblePool = all.filter(index => index >= DIVISIBLE_START_INDEX);
  const normalPool = all.filter(index => index < MYSTERY_START_INDEX);

  const pickVaried = (pool, take) => {
    const fresh = shuffle(pool.filter(index => !previous.has(index)));
    const repeated = shuffle(pool.filter(index => previous.has(index)));
    return [...fresh, ...repeated].slice(0, take);
  };

  const mysteryQuota = options.includeMystery ? MYSTERY_QUOTA : 0;
  const divisibleQuota = options.includeDivisible ? DIVISIBLE_QUOTA : 0;
  const mysterySelected = pickVaried(mysteryPool, Math.min(mysteryQuota, mysteryPool.length, count));
  const divisibleSelected = pickVaried(divisiblePool, Math.min(divisibleQuota, divisiblePool.length, count - mysterySelected.length));
  const normalSelected = pickVaried(normalPool, count - mysterySelected.length - divisibleSelected.length);
  const deck = shuffle([...mysterySelected, ...divisibleSelected, ...normalSelected]);
  previousDeck = deck;
  return deck;
};

const createCode = () => {
  const alphabet = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  for (let attempt = 0; attempt < 100; attempt += 1) {
    const code = Array.from(
      { length: 5 },
      () => alphabet[Math.floor(Math.random() * alphabet.length)]
    ).join('');
    if (!rooms.has(code)) return code;
  }
  throw new Error('Nie udało się utworzyć kodu pokoju.');
};

const makePlayer = (name, index, isBot = false) => ({
  id: crypto.randomUUID(),
  token: crypto.randomBytes(24).toString('hex'),
  name,
  cash: START_CASH,
  properties: [],
  avatarIndex: index % MAX_PLAYERS,
  isBot
});

const publicPlayer = player => ({
  id: player.id,
  name: player.name,
  cash: player.cash,
  properties: player.properties,
  avatarIndex: player.avatarIndex,
  isBot: Boolean(player.isBot)
});

const snapshot = (room, selfId) => ({
  serverNow: Date.now(),
  revision: room.revision,
  roomCode: room.code,
  selfId,
  hostId: room.hostId,
  phase: room.phase,
  players: room.players.map(publicPlayer),
  readyIds: [...room.ready],
  round: room.round,
  totalListings: room.deck.length,
  listingId: room.deck[room.round] ?? null,
  auctionStartsAt: room.auctionStartsAt,
  auctionEndsAt: room.auctionEndsAt,
  result: room.result,
  options: { ...room.options }
});

const writeEvent = (response, eventName, data) => {
  response.write(`event: ${eventName}\ndata: ${JSON.stringify(data)}\n\n`);
};

const broadcast = room => {
  room.revision += 1;
  room.updatedAt = Date.now();
  for (const [playerId, responses] of room.streams) {
    for (const response of responses) writeEvent(response, 'state', snapshot(room, playerId));
  }
};

const clearRoomTimers = room => {
  for (const timer of room.timers) clearTimeout(timer);
  room.timers.clear();
};

const schedule = (room, callback, delay) => {
  const timer = setTimeout(() => {
    room.timers.delete(timer);
    callback();
  }, delay);
  room.timers.add(timer);
};

// Boty w pokoju sieciowym licytują dokładnie tak samo jak w trybie solo: bez
// znajomości czynszu, cel to losowy ułamek ceny startowej. Każdy bot dostaje
// jeden zaplanowany "zakup" o wyliczonym czasie; jeśli ktoś kupi wcześniej,
// settleBuy sam odrzuci spóźnioną próbę (faza nie będzie już 'auction').
const NETWORK_BOT_AGGRO_MIN = .29;
const NETWORK_BOT_AGGRO_MAX = .60;
const NETWORK_BOT_DELAY_MIN = 2_500;
const NETWORK_BOT_DELAY_MAX = 5_400;
const NETWORK_BOT_REACTION_MIN = 150;
const NETWORK_BOT_REACTION_MAX = 400;

const scheduleBotBids = room => {
  const bots = room.players.filter(player => player.isBot);
  if (!bots.length) return;
  const isFinalRound = room.round >= room.deck.length - 1;
  for (const bot of bots) {
    const aggro = NETWORK_BOT_AGGRO_MIN + Math.random() * (NETWORK_BOT_AGGRO_MAX - NETWORK_BOT_AGGRO_MIN);
    const target = isFinalRound ? bot.cash : Math.round(Math.min(bot.cash, START_PRICE * aggro));
    const notBeforeMs = NETWORK_BOT_DELAY_MIN + Math.random() * (NETWORK_BOT_DELAY_MAX - NETWORK_BOT_DELAY_MIN);
    const reactionMs = NETWORK_BOT_REACTION_MIN + Math.random() * (NETWORK_BOT_REACTION_MAX - NETWORK_BOT_REACTION_MIN);
    const elapsedForTarget = target >= START_PRICE ? 0 : AUCTION_MS * (1 - target / START_PRICE);
    const commitMs = Math.max(notBeforeMs, elapsedForTarget) + reactionMs;
    if (commitMs >= AUCTION_MS) continue;
    schedule(room, () => {
      const outcome = settleBuy(room, bot);
      if (outcome.ok && room.result?.divisible) resolveDivide(room, bot.cash >= DIVIDE_COST);
    }, commitMs);
  }
};

const beginAuction = room => {
  if (room.phase !== 'countdown') return;
  room.phase = 'auction';
  room.auctionStartsAt = Date.now();
  room.auctionEndsAt = room.auctionStartsAt + AUCTION_MS;
  broadcast(room);
  const listingId = room.deck[room.round];
  const threshold = familyThresholdFor(listingId);
  const familyDelay = Math.max(0, AUCTION_MS * (1 - threshold / START_PRICE));
  schedule(room, () => settleFamilyBuy(room), familyDelay + 25);
  scheduleBotBids(room);
};

const beginCountdown = room => {
  if (room.phase !== 'ready') return;
  room.phase = 'countdown';
  room.auctionStartsAt = Date.now() + COUNTDOWN_MS;
  room.auctionEndsAt = room.auctionStartsAt + AUCTION_MS;
  broadcast(room);
  schedule(room, () => beginAuction(room), COUNTDOWN_MS);
};

// Boty nie mają klienta, więc nigdy same nie wywołają /ready — bez tego pokój
// czekałby na nie w nieskończoność.
const markBotsReady = room => {
  for (const player of room.players) if (player.isBot) room.ready.add(player.id);
};

const advanceRound = room => {
  if (room.phase !== 'result') return;
  room.round += 1;
  room.ready.clear();
  markBotsReady(room);
  room.result = null;
  room.auctionStartsAt = null;
  room.auctionEndsAt = null;
  room.phase = room.round >= room.deck.length ? 'final' : 'ready';
  broadcast(room);
};

const settleUnsold = room => {
  if (room.phase !== 'auction') return false;
  clearRoomTimers(room);
  room.phase = 'result';
  room.result = {
    type: 'unsold',
    listingId: room.deck[room.round],
    price: 0,
    playerId: null
  };
  broadcast(room);
  schedule(room, () => advanceRound(room), RESULT_MS);
  return true;
};

// Poniżej familyThresholdFor() nikt z graczy nie kupił, zanim cena tam
// dotarła — ofertę bierze ktoś, kto naprawdę w niej zamieszka. Ten timer
// zastępuje settleUnsold() w normalnym przebiegu gry (próg jest zawsze > 0,
// więc odpala się wcześniej niż koniec aukcji); settleUnsold zostaje jako
// zabezpieczenie/do testów, ale w praktyce już nie powinien się odpalać.
const settleFamilyBuy = room => {
  if (room.phase !== 'auction') return false;
  clearRoomTimers(room);
  room.phase = 'result';
  const listingId = room.deck[room.round];
  room.result = {
    type: 'family',
    listingId,
    price: familyThresholdFor(listingId),
    playerId: null
  };
  broadcast(room);
  schedule(room, () => advanceRound(room), RESULT_MS);
  return true;
};

const DIVIDE_DECISION_MS = 15_000;

const settleBuy = (room, player) => {
  if (room.phase !== 'auction') return { ok: false, status: 409, error: 'Aukcja nie jest aktywna.' };
  const listingId = room.deck[room.round];
  const elapsed = Math.max(0, Date.now() - room.auctionStartsAt);
  const price = Math.max(0, Math.floor(START_PRICE * (1 - elapsed / AUCTION_MS)));
  const threshold = familyThresholdFor(listingId);
  if (price <= threshold) return { ok: false, status: 409, error: 'Cena spadła już poniżej progu — mieszkanie bierze ktoś inny.' };
  if (price > player.cash) return { ok: false, status: 409, error: 'Nie masz wystarczającego salda.' };

  clearRoomTimers(room);
  const divisible = listingId >= DIVISIBLE_START_INDEX;
  player.cash -= price;
  player.properties.push({ listingId, rent: LISTING_RENTS[listingId], paid: price });
  room.phase = 'result';
  room.result = divisible
    ? { type: 'sold', listingId, price, playerId: player.id, divisible: true, divideDecision: null }
    : { type: 'sold', listingId, price, playerId: player.id };
  broadcast(room);
  if (divisible) schedule(room, () => resolveDivide(room, false), DIVIDE_DECISION_MS);
  else schedule(room, () => advanceRound(room), RESULT_MS);
  return { ok: true, price };
};

// Kupujący ma czas do DIVIDE_DECISION_MS na decyzję o podziale; jeśli nie
// zdąży (np. rozłączy się), zaszyte bezpieczeństwo zostawia mieszkanie w
// całości, żeby reszta pokoju nie utknęła w oczekiwaniu.
const resolveDivide = (room, divide) => {
  if (room.phase !== 'result' || !room.result?.divisible || room.result.divideDecision != null) return false;
  clearRoomTimers(room);
  const buyer = room.players.find(item => item.id === room.result.playerId);
  if (divide && buyer && buyer.cash >= DIVIDE_COST) {
    buyer.cash -= DIVIDE_COST;
    const perUnit = dividedRentPerUnit(LISTING_RENTS[room.result.listingId]);
    buyer.properties.pop();
    buyer.properties.push({ listingId: room.result.listingId, rent: perUnit, paid: 0 });
    buyer.properties.push({ listingId: room.result.listingId, rent: perUnit, paid: 0 });
    room.result.divideDecision = 'split';
  } else {
    room.result.divideDecision = 'keep';
  }
  broadcast(room);
  schedule(room, () => advanceRound(room), RESULT_MS);
  return true;
};

const newRoom = name => {
  const code = createCode();
  const host = makePlayer(name, 0);
  const room = {
    code,
    hostId: host.id,
    phase: 'lobby',
    players: [host],
    ready: new Set(),
    deck: [],
    round: 0,
    auctionStartsAt: null,
    auctionEndsAt: null,
    result: null,
    options: { includeMystery: false, includeDivisible: false },
    streams: new Map(),
    timers: new Set(),
    revision: 0,
    updatedAt: Date.now()
  };
  rooms.set(code, room);
  return { room, player: host };
};

const authenticate = (room, playerId, token) => {
  if (!room) return null;
  return room.players.find(player => player.id === playerId && player.token === token) || null;
};

const readBody = request => new Promise((resolve, reject) => {
  let body = '';
  request.setEncoding('utf8');
  request.on('data', chunk => {
    body += chunk;
    if (body.length > 12_000) reject(new Error('Żądanie jest za duże.'));
  });
  request.on('end', () => {
    try { resolve(body ? JSON.parse(body) : {}); }
    catch { reject(new Error('Nieprawidłowe dane.')); }
  });
  request.on('error', reject);
});

const serveFile = (response, requestPath) => {
  const relativePath = requestPath === '/' ? 'index.html' : requestPath.replace(/^\//, '');
  if (relativePath !== 'index.html' && !relativePath.startsWith('assets/')) return false;
  const extension = path.extname(relativePath).toLowerCase();
  const contentTypes = {
    '.html': 'text/html; charset=utf-8',
    '.jpg': 'image/jpeg',
    '.jpeg': 'image/jpeg',
    '.png': 'image/png',
    '.webp': 'image/webp'
  };

  const embeddedAsset = EMBEDDED_ASSETS.get(relativePath);
  if (embeddedAsset) {
    response.writeHead(200, {
      'content-type': contentTypes[extension] || 'application/octet-stream',
      'cache-control': 'public, max-age=86400'
    });
    response.end(Buffer.from(embeddedAsset, 'base64'));
    return true;
  }

  const filePath = path.resolve(rootDirectory, relativePath);
  const hasEmbeddedIndex = relativePath === 'index.html' && Boolean(EMBEDDED_INDEX_HTML);
  if (!filePath.startsWith(rootDirectory + path.sep)) return false;
  if (!hasEmbeddedIndex && (!fs.existsSync(filePath) || !fs.statSync(filePath).isFile())) return false;
  response.writeHead(200, {
    'content-type': contentTypes[extension] || 'application/octet-stream',
    'cache-control': extension === '.html' ? 'no-store' : 'public, max-age=86400'
  });
  if (extension === '.html') {
    // Na zwykłym wdrożeniu źródłem prawdy jest index.html z repozytorium.
    // Kopia osadzona pozostaje wyłącznie awaryjnym wariantem jednoplikowym.
    let html = (fs.existsSync(filePath) ? fs.readFileSync(filePath, 'utf8') : EMBEDDED_INDEX_HTML)
      .replace(
        'Prototyp lokalny: tryb demo symuluje pozostałe telefony botami. Pokój sieciowy będzie kolejną warstwą — reguły i ekrany są już wspólne dla obu trybów.',
        'Mikrokawalerki są łudząco podobne do prawdziwych, ale nie przedstawiają rzeczywistych ofert. Gra ma charakter satyryczny.'
      )
      .replace('W prototypie dobierz graczy testowych', 'W trybie demo dobierz graczy testowych')
      .replace(
        'Kupuj metry, których prawie nie ma. Wygrywa, kto zgarnie największy czynsz.',
        'Kupuj mikrokawalerki i wyciśnij ile się da z metrów i ludzi.'
      )
      .replace('Kupuj mikro-kawalerki i wyciśnij ile się da z metrów i ludzi.', 'Kupuj mikrokawalerki i wyciśnij ile się da z metrów i ludzi.')
      .replace('placeholder="np. Rafał"', 'placeholder="np. Fliper"')
      .replace('const AUCTION_MS = 8_000;', 'const AUCTION_MS = 10_000;');

    // Starszy index.html ma tylko 20 ofert. Dopisujemy nowe bez konieczności
    // osobnego wgrywania strony przez użytkownika.
    if (!html.includes('syntheticPhoto(31)')) {
      html = html.replace(
        'photos: syntheticPhoto(20) }\n      ];',
        `photos: syntheticPhoto(20) },\n${EXTRA_LISTINGS_HTML}\n      ];`
      );
    }

    // Jednoplikowa aktualizacja synchronizuje także czynsze w starszym index.html.
    LISTING_RENTS.forEach((rent, index) => {
      html = html.replace(
        new RegExp(`rent:\\s*\\d+, photos: syntheticPhoto\\(${index + 1}\\)`),
        `rent: ${rent}, photos: syntheticPhoto(${index + 1})`
      );
    });

    // Starszy index.html dostaje tę samą ochronę przed powtarzającą się talią w demo.
    if (!html.includes('varied-demo-deck') && !html.includes('chooseVariedListings')) {
      html = html.replace(
        'state.listings = shuffle(LISTINGS).slice(0, state.playerCount + 8);',
        `// varied-demo-deck
        const previous = new Set(state.previousListingIndexes || []);
        const indexedListings = LISTINGS.map((listing, index) => ({ listing, index }));
        const freshListings = shuffle(indexedListings.filter(item => !previous.has(item.index)));
        const repeatedListings = shuffle(indexedListings.filter(item => previous.has(item.index)));
        const selectedListings = [...freshListings, ...repeatedListings].slice(0, state.playerCount + 8);
        state.previousListingIndexes = selectedListings.map(item => item.index);
        state.listings = selectedListings.map(item => item.listing);`
      );
    }

    // Jednoplikowa aktualizacja musi również naprawić starszy index.html,
    // jeśli klient nie wgrał jeszcze wersji z zabezpieczeniem finału.
    if (!html.includes('finalFallbackTimer') && !html.includes('network-final-fallback')) {
      html = html.replace(
        "if (snapshot.phase === 'result') return showNetworkResult(snapshot);",
        `if (snapshot.phase === 'result') {
          showNetworkResult(snapshot);
          // network-final-fallback: każdy telefon pokaże finał, nawet jeśli zgubi ostatnie SSE.
          if (snapshot.round + 1 >= snapshot.totalListings) {
            setTimeout(() => {
              if (!network.active || state.phase !== 'result') return;
              $('#result-overlay').hidden = true;
              showFinal();
            }, 1_800);
          }
          return;
        }`
      );
    }

    response.end(html);
    return true;
  }
  fs.createReadStream(filePath).pipe(response);
  return true;
};

export const createRequestHandler = () => async (request, response) => {
  const requestUrl = new URL(request.url, 'http://localhost');

  if (request.method === 'GET' && requestUrl.pathname === '/healthz') {
    return json(response, 200, { ok: true, rooms: rooms.size });
  }

  if (request.method === 'GET' && requestUrl.pathname === '/robots.txt') {
    response.writeHead(200, { 'content-type': 'text/plain; charset=utf-8' });
    return response.end('User-agent: *\nDisallow: /\n');
  }

  const streamMatch = requestUrl.pathname.match(/^\/api\/rooms\/([A-Z0-9]{5})\/stream$/);
  if (request.method === 'GET' && streamMatch) {
    const room = rooms.get(streamMatch[1]);
    const player = authenticate(room, requestUrl.searchParams.get('playerId'), requestUrl.searchParams.get('token'));
    if (!player) return json(response, 401, { error: 'Nieprawidłowa sesja gracza.' });
    response.writeHead(200, {
      'content-type': 'text/event-stream; charset=utf-8',
      'cache-control': 'no-cache, no-transform',
      connection: 'keep-alive',
      'x-accel-buffering': 'no'
    });
    response.write('retry: 1500\n\n');
    if (!room.streams.has(player.id)) room.streams.set(player.id, new Set());
    room.streams.get(player.id).add(response);
    writeEvent(response, 'state', snapshot(room, player.id));
    const heartbeat = setInterval(() => response.write(': ping\n\n'), 20_000);
    request.on('close', () => {
      clearInterval(heartbeat);
      room.streams.get(player.id)?.delete(response);
    });
    return;
  }

  if (request.method === 'POST' && requestUrl.pathname === '/api/rooms') {
    try {
      const body = await readBody(request);
      const name = cleanName(body.name);
      if (!name) return json(response, 400, { error: 'Podaj imię albo przezwisko.' });
      const { room, player } = newRoom(name);
      return json(response, 201, { roomCode: room.code, playerId: player.id, token: player.token });
    } catch (error) {
      return json(response, 400, { error: error.message });
    }
  }

  const actionMatch = requestUrl.pathname.match(/^\/api\/rooms\/([A-Z0-9]{5})\/(join|options|start|addbot|again|ready|buy|divide)$/);
  if (request.method === 'POST' && actionMatch) {
    const room = rooms.get(actionMatch[1]);
    if (!room) return json(response, 404, { error: 'Nie ma pokoju o takim kodzie.' });
    try {
      const body = await readBody(request);
      const action = actionMatch[2];

      if (action === 'join') {
        if (room.phase !== 'lobby') return json(response, 409, { error: 'Ta gra już się rozpoczęła.' });
        if (room.players.length >= MAX_PLAYERS) return json(response, 409, { error: 'Pokój jest pełny.' });
        const name = cleanName(body.name);
        if (!name) return json(response, 400, { error: 'Podaj imię albo przezwisko.' });
        const player = makePlayer(name, room.players.length);
        room.players.push(player);
        broadcast(room);
        return json(response, 201, { roomCode: room.code, playerId: player.id, token: player.token });
      }

      const player = authenticate(room, body.playerId, body.token);
      if (!player) return json(response, 401, { error: 'Nieprawidłowa sesja gracza.' });

      if (action === 'options') {
        if (player.id !== room.hostId) return json(response, 403, { error: 'Tylko gospodarz może zmieniać opcje gry.' });
        if (room.phase !== 'lobby') return json(response, 409, { error: 'Opcje można zmieniać tylko w poczekalni.' });
        room.options.includeMystery = Boolean(body.includeMystery);
        room.options.includeDivisible = Boolean(body.includeDivisible);
        broadcast(room);
        return json(response, 200, { ok: true });
      }

      if (action === 'addbot') {
        if (player.id !== room.hostId) return json(response, 403, { error: 'Tylko gospodarz może dodawać boty.' });
        if (room.phase !== 'lobby') return json(response, 409, { error: 'Boty można dodawać tylko w poczekalni.' });
        if (room.players.length >= MAX_PLAYERS) return json(response, 409, { error: 'Pokój jest pełny.' });
        const botCount = room.players.filter(item => item.isBot).length;
        if (botCount >= MAX_BOTS) return json(response, 409, { error: `Maksymalnie ${MAX_BOTS} boty — reszta miejsc jest dla prawdziwych graczy.` });
        const bot = makePlayer(BOT_NAMES[botCount] || `Bot ${botCount + 1}`, room.players.length, true);
        room.players.push(bot);
        broadcast(room);
        return json(response, 201, { ok: true, playerId: bot.id });
      }

      if (action === 'start') {
        if (player.id !== room.hostId) return json(response, 403, { error: 'Tylko gospodarz może rozpocząć grę.' });
        if (room.phase !== 'lobby') return json(response, 409, { error: 'Gra już się rozpoczęła.' });
        if (room.players.length < MIN_PLAYERS) return json(response, 409, { error: 'Potrzeba co najmniej 2 graczy.' });
        const humanCount = room.players.filter(item => !item.isBot).length;
        if (humanCount < MIN_HUMAN_PLAYERS) return json(response, 409, { error: 'Potrzeba co najmniej 2 prawdziwych graczy — boty same nie wystarczą.' });
        room.deck = createVariedDeck(room.players.length + 8, room.options);
        room.round = 0;
        room.phase = 'ready';
        room.ready.clear();
        markBotsReady(room);
        room.result = null;
        broadcast(room);
        return json(response, 200, { ok: true });
      }

      if (action === 'again') {
        if (player.id !== room.hostId) return json(response, 403, { error: 'Tylko gospodarz może zacząć nową rundę.' });
        if (room.phase !== 'final') return json(response, 409, { error: 'Gra jeszcze się nie skończyła.' });
        clearRoomTimers(room);
        room.players.forEach(roomPlayer => {
          roomPlayer.cash = START_CASH;
          roomPlayer.properties = [];
        });
        room.deck = createVariedDeck(room.players.length + 8, room.options);
        room.round = 0;
        room.phase = 'ready';
        room.ready.clear();
        markBotsReady(room);
        room.result = null;
        room.auctionStartsAt = null;
        room.auctionEndsAt = null;
        broadcast(room);
        return json(response, 200, { ok: true });
      }

      if (action === 'divide') {
        if (room.phase !== 'result' || !room.result?.divisible) {
          return json(response, 409, { error: 'Teraz nie można podjąć tej decyzji.' });
        }
        if (player.id !== room.result.playerId) {
          return json(response, 403, { error: 'Tylko kupujący podejmuje tę decyzję.' });
        }
        if (room.result.divideDecision != null) {
          return json(response, 409, { error: 'Decyzja już zapadła.' });
        }
        resolveDivide(room, Boolean(body.divide));
        return json(response, 200, { ok: true });
      }

      if (action === 'ready') {
        if (room.phase !== 'ready') return json(response, 409, { error: 'Teraz nie można zgłosić gotowości.' });
        room.ready.add(player.id);
        broadcast(room);
        if (room.ready.size === room.players.length) beginCountdown(room);
        return json(response, 200, { ok: true });
      }

      const outcome = settleBuy(room, player);
      return json(response, outcome.ok ? 200 : outcome.status, outcome);
    } catch (error) {
      return json(response, 400, { error: error.message });
    }
  }

  if (request.method === 'GET' && serveFile(response, decodeURIComponent(requestUrl.pathname))) return;
  json(response, 404, { error: 'Nie znaleziono.' });
};

export const createKlitkaServer = () => http.createServer(createRequestHandler());

export const __test = {
  rooms,
  newRoom,
  makePlayer,
  authenticate,
  settleBuy,
  settleUnsold,
  settleFamilyBuy,
  resolveDivide,
  beginCountdown,
  beginAuction,
  clearRoomTimers,
  createVariedDeck
};

const cleanup = setInterval(() => {
  const cutoff = Date.now() - 2 * 60 * 60 * 1000;
  for (const [code, room] of rooms) {
    if (room.updatedAt < cutoff) {
      clearRoomTimers(room);
      rooms.delete(code);
    }
  }
}, 60_000);
cleanup.unref();

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const port = Number(process.env.PORT || 8765);
  createKlitkaServer().listen(port, '0.0.0.0', () => {
    console.log(`KLITKA online: http://0.0.0.0:${port}`);
  });
}
